bool hasCloseElements(List<double> numbers, double threshold) {
  if (numbers.isEmpty || threshold < 0.0) return false;

  for (int i = 1; i < numbers.length; i++) {
    final prev = numbers[i - 1];
    final curr = numbers[i];
    final diff = abs(curr - prev);

    if (diff <= threshold) {
      return true;
    }
  }

