List<int> parseNestedParens(String parenString) {
  List<int> result = [];
  int depth = 0;

  for (int i = 0; i < parenString.length; i++) {
    if (parenString[i] == '(') {
      depth++;
      // Calculate the index of the matching closing parenthesis
      int closeIndex = findMatchingClose(parenString, i);

      if (depth > 1) {
        // If not at the top level, add the length between current and previous open
        int prevOpen = -1;
        for (int j = i - 1; j >= 0 && depth > 1; j--) {
          if (parenString[j] == '(') {
            prevOpen = j;
            break;
          }
        }
        if (prevOpen != -1) {
          result.add(closeIndex - prevOpen + 1); 
        } else {
          result.add(0); // No previous opening bracket
        }
      } else {
        result.add(0); // First-level parentheses do not count as nested
      }

      i = closeIndex; // Skip to after the closing parenthesis
    }
  }

  return result;
}

