List<double> findClosestElements(List<double> numbers) {
  if (numbers.isEmpty || numbers.length < 2) return numbers;

  double left = 0;
  double right = numbers.length - 1;

  while (left <= right) {
    double mid = (left + right) / 2;

    if (mid == left) {
      // If the midpoint is at the first element, compare with next
      int index = left.toInt();
      if (index < numbers.length - 1) {
        return [numbers[index], numbers[index+1]];
      } else {
        return [numbers[index]];
      }
    } else if (mid == right) {
      // If the midpoint is at last element, compare with previous
      int index = right.toInt();
      if (index > 0) {
        return [numbers[index-1], numbers[index]];
      } else {
        return [numbers[index]];
      }
    }

    int lIndex = mid.floor().toInt();
    int rIndex = (mid.ceil()).toInt();

    double diffLeft = numbers[lIndex] - mid;
    double diffRight = numbers[rIndex] - mid;

    if (diffLeft * diffRight < 0) { 
      // Midpoint between two different signs
      return [numbers[lIndex], numbers[rIndex]];
    } else if (diffLeft < 0 && diffRight < 0) {
      // Both are on same side of target; move to the right
      left = mid + 1e-9;
    } else {
      // Both are on same side or one is zero; move to the left
      right = mid - 1e-9;
    }
  }

  // Fallback when loop ends without returning earlier
  int closestIndex = left.toInt();
  if (closestIndex >= numbers.length) closestIndex--;
  if (closestIndex < 0) closestIndex++;
