// Helper class for merging multiple sets
class UnionFind<T> {
  final List<T> _sets;

  UnionFind(this._sets);

  T mergeAll() {
    if (_sets.isEmpty) return null;

    var merged = _sets.first;
    for (int i = 1; i < _sets.length; i++) {
      merged = UnionFind([merged, _sets[i]]).merge();
    }
    return merged;
  }

  T merge() {
    if (_sets.length != 2) throw ArgumentError('Exactly two sets required');

    final Set<T> merged = _sets[0] as Set<T>;
    merged.addAll(_sets[1] as Set<T>);
    return merged;
  }
}
