import 'dart:math';

List<int> maximum(List<int> arr, int k) {
  if (k == 0 || arr.isEmpty) return List.empty();

  var n = arr.length;
  if (n <= k) return List.unmodifiable(arr);

  // Create a max heap to find the k-th largest element efficiently
  var heap = PriorityQueue<int>((a, b) => b.compareTo(a));
  for (var i = 0; i < k; i++) {
    heap.add(arr[i]);
  }

  for (var i = k; i < n; i++) {
    if (arr[i] > heap.peek()) {
      heap.remove(heap.peek());
      heap.add(arr[i]);
    }
  }

  var result = [];
  for (var _ in Range(k)) {
    result.add(heap.poll()!);
  }
  return result.reversed.toList(); 
}
```

