List<int> minPath(List<List<int>> grid, int k) {
  final rows = grid.length;
  final cols = grid[0].length;

  // Directions for moving (right and down)
  List<Offset> directions = [Offset(0,1), Offset(1,0)];

  // Priority queue to store the path cost, steps taken, current position
  PriorityQueue pq = PriorityQueue((a, b) => a.cost - b.cost);
  pq.add(PriorityQueueEntry(0, 0, 0, 0));

  // Set of visited positions with the number of steps taken
  Set<String> visited = {};

  while (!pq.isEmpty) {
    var entry = pq.removeFirst();
    final cost = entry.cost;
    final x = entry.x;
    final y = entry.y;
    final steps = entry.steps;

    if (x == rows-1 && y == cols-1) {
      return [steps];
    }

    if (visited.containsKey('$x,$y') && visited['$x,$y'] <= steps) continue;
    visited['$x,$y'] = steps;

    for (var dir in directions) {
      final nx = x + dir.dx;
      final ny = y + dir.dy;

      if (nx >= 0 && ny >= 0 && nx < rows && ny < cols) {
        final nextCost = cost + grid[nx][ny];

        if (nextCost > k) continue; // Skip paths exceeding budget

        pq.add(PriorityQueueEntry(nextCost, nx, ny, steps+1));
      }
    }
  }

  throw Exception('No valid path found within budget');
}

class PriorityQueueEntry implements Comparable<PriorityQueueEntry> {
  final int cost;
  final int x;
  final int y;
  final int steps;

  PriorityQueueEntry(this.cost, this.x, this.y, this.steps);

  @override
  int compareTo(other) {
    return cost.compareTo(other.cost);
  }
}

