import 'dart:math';

List<int> minPath(List<List<int>> grid, int k) {
  final rows = grid.length;
  if (rows == 0) return [];
  final cols = grid[0].length;

  // Initialize a DP table to keep track of the minimum path sum for each cell with i steps taken.
  List<List<int>> dp = List.generate(rows, (_) => List.filled(cols, 0));

  // Initialize first row and column based on starting point at [0][0]
  dp[0][0] = grid[0][0];

  for (int i = 1; i < rows; ++i) {
    dp[i][0] = dp[i - 1][0] + grid[i][0];
  }
  for (int j = 1; j < cols; ++j) {
    dp[0][j] = dp[0][j - 1] + grid[0][j];
  }

  for (int step = 2; step <= k; ++step) {
    for (int i = 0; i < rows; ++i) {
      for (int j = 0; j < cols; ++j) {
        var prevMin = double.infinity;

        // Check all possible previous positions from which we could come here in one move:
        // Up, left, up-left diagonal

        if (i > 0) prevMin = min(prevMin, dp[i-1][j]);
        if (j > 0) prevMin = min(prevMin, dp[i][j-1]);
        if (i > 0 && j > 0) prevMin = min(prevMin, dp[i-1][j-1]);

        dp[i][j] = prevMin + grid[i][j]; 
      }
    }
  }

  // Find the minimum value in the last step's dp state
  int result = double.infinity;
  for (var val in dp[k % rows]) {
    result = min(result, val);
  }

  return [result];
}
