num combinations(num n, num k) {
  if (k > n || k < 0) return 0;
  if (k == 0 || k == n) return 1;

  // Calculate the combination using logarithms to avoid integer overflow
  double logNumerator = 0.0;
  double logDenominator = 0.0;

  for (var i = 1; i <= k; ++i) {
    logNumerator += ln(i + n - k);
    logDenominator += ln(i);
  }

  return exp(logNumerator - logDenominator);
}

