List<String> factorize(String numberStr) {
  // Convert to integer and check if it's a valid positive integer.
  try {
    final num = int.parse(numberStr);
    if (num <= 0) throw ArgumentError('Number must be a positive integer.');
  } on FormatException catch (_) {
    throw ArgumentError('Invalid input. Please enter a positive integer.');
  }

  final List<String> primeFactors = [];

  int n = int.parse(numberStr);

  // Check divisibility by 2 first
  while (n % 2 == 0) {
    primeFactors.add("2");
    n ~/= 2;
  }

  // Now check odd numbers starting from 3 up to sqrt(n)
  for (int i = 3; i * i <= n; i += 2) {
    while (n % i == 0) {
      primeFactors.add("$i");
      n ~/= i;
    }
  }

  // If remaining n is greater than 1, it's a prime number itself
  if (n > 1) {
    primeFactors.add("$n");
  }

  return primeFactors;
}
