bool cycpatternCheck(String a, String b) {
  if (a.isEmpty || b.isEmpty) return false;

  final len = a.length;
  int maxShifts = min(len - 1, b.length);

  for (int i = 0; i <= maxShifts; i++) {
    bool match = true;

    for (int j = 0; j < len; j++) {
      int shift = (i + j) % len;

      if (b[j] != a[shift]) {
        match = false;
        break;
      }
    }

    if (match) return true;
  }

  return false;
}
